import { describe, expect, it } from 'vitest';
import { apiPage } from './api.ts';
import { renderMarkdown } from './render.ts';

const PILL = '<span class="ui-pill">Experimental</span>';

describe('apiPage.source', () => {
  it("drops the generator's note, the page's last line", () => {
    const src =
      '# @isoloop/host\n\nThe main thread.\n\n<!-- Generated by scripts/docs/api.ts: do not edit. -->\n';
    expect(apiPage.source(src)).toBe('# @isoloop/host\n\nThe main thread.\n\n');
    expect(renderMarkdown(apiPage.source(src)).html).not.toContain('&lt;!--');
  });

  it('keeps a page without one as it is', () => {
    expect(apiPage.source('# A\n\nB.\n')).toBe('# A\n\nB.\n');
  });
});

const page = (body: string): string =>
  apiPage.html(renderMarkdown(`# @isoloop/balancer\n\nPlacement.\n\n${body}`).body);

describe('apiPage.html', () => {
  it("turns an export's Experimental lead-in into the pill, keeping the text after it", () => {
    const html = page(
      '### `createBalancer`\n\n**Experimental.** The policy may change before 1.0.\n',
    );
    expect(html).toContain(
      `<p class="doc-experimental">${PILL} The policy may change before 1.0.</p>`,
    );
    expect(html).not.toContain('<strong>Experimental.</strong>');
  });

  it('turns a lead-in alone into the pill alone', () => {
    expect(page('### `Balancer`\n\n**Experimental.**\n')).toContain(
      `<p class="doc-experimental">${PILL}</p>`,
    );
  });

  it("turns a member's lead-in at the start of its cell into the pill", () => {
    const html = page(
      '### `Kernel`\n\n| Member | Description |\n| --- | --- |\n| `tap` | **Experimental.** Copies records. |\n| `stop` | **Experimental.** |\n',
    );
    expect(html).toContain(`<td>${PILL} Copies records.</td>`);
    expect(html).toContain(`<td>${PILL}</td>`);
  });

  it('leaves "Experimental." elsewhere alone: not after an h3, or not at the start', () => {
    const body =
      '## `@isoloop/host`\n\n**Experimental.** Not an export.\n\n### `x`\n\nIt is **Experimental.** here.\n';
    const html = page(body);
    expect(html).not.toContain('ui-pill');
  });
});
